    align-items: center;
    padding: 1rem;
    border-bottom: 1px solid #e1e5e9;
    transition: background-color 0.3s ease;
}

li:last-child {
    border-bottom: none;
}

li:hover {
    background-color: #f8f9fa;
}

.task-text {
    flex: 1;
    margin-left: 1rem;
}

.task-text.completed {
    text-decoration: line-through;
    color: #6c757d;
