content.text:
/* Reset and base styles */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  line-height: 1.6;
  color: #333;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  min-height: 100vh;
}

header {
  background: rgba(255, 255, 255, 0.1);
  padding: 2rem 0;
  text-align: center;
  backdrop-filter: blur(10px);
}

h1 {
  color: white;
  font-size: 2.5rem;
  font-weight: 300;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.3);
}

main {
  max-width: 800px;
  margin: 0 auto;
  padding: 2rem;
}

/* Task form styles */
.task-form {
  background: white;
  padding: 2rem;
  border-radius: 10px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
  margin-bottom: 2rem;
}

form {
  display: flex;
  gap: 1rem;
  align-items: center;
}

input[type='text'] {
  flex: 1;
  padding: 1rem;
  border: 2px solid #e1e5e9;
  border-radius: 5px;
  font-size: 1rem;
  transition: border-color 0.3s ease;
}

input[type='text']:focus {
  outline: none;
  border-color: #667eea;
  box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
}

button {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  border: none;
  padding: 1rem 2rem;
  border-radius: 5px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

button:hover {
  transform: translateY(-2px);
  box-shadow: 0 5px 15px rgba(102, 126, 234, 0.3);
}

button:active {
  transform: translateY(0);
}

/* Task list styles */
.task-list {
  background: white;
  padding: 2rem;
  border-radius: 10px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
}

h2 {
  margin-bottom: 1.5rem;
  color: #333;
  font-weight: 600;
}

ul {
  list-style: none;
}

li {
  display: flex;
  align-items: center;
  padding: 1rem;
  border-bottom: 1px solid #e1e5e9;
  transition: background-color 0.3s ease;
}

li:last-child {
  border-bottom: none;
}

li:hover {
  background-color: #f8f9fa;
}

.task-text {
  flex: 1;
  margin-left: 1rem;
}

.task-text.completed {
  text-decoration: line-through;
  color: #6c757d;
}

.task-actions {
  display: flex;
  gap: 0.5rem;
}

.task-actions button {
  padding: 0.5rem 1rem;
  font-size: 0.9rem;
  border-radius: 3px;
}

.complete-btn {
  background: #28a745;
}

.complete-btn:hover {
  background: #218838;
}

.delete-btn {
  background: #dc3545;
}

.delete-btn:hover {
  background: #c82333;
}

/* Screen reader only class */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* Responsive design */
@media (max-width: 768px) {
  main {
    padding: 1rem;
  }

  h1 {
    font-size: 2rem;
  }

  form {
    flex-direction: column;
    align-items: stretch;
  }

  button {
    align-self: flex-end;
    width: auto;
  }

  li {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.5rem;
  }

  .task-actions {
    align-self: flex-end;
  }
}

@media (max-width: 480px) {
  .task-form,
  .task-list {
    padding: 1rem;
  }

  input[type='text'] {
    padding: 0.75rem;
  }

  button {
    padding: 0.75rem 1.5rem;
  }
}

