        pending: 'No pending tasks.',
      };
      emptyMessage.innerHTML = `<p style="text-align: center; color: #6c757d; font-style: italic;">${messages[this.currentFilter]}</p>`;
      this.tasksList.appendChild(emptyMessage);
      return;
