    filteredTasks.forEach((task) => {
      const li = document.createElement('li');
      const completionText = task.completed ? this.formatCompletionTime(task.completedAt) : '';
      const completionLabel = completionText ? `<span class="completion-time">${completionText}</span>` : '';

      const isEditing = this.editingTaskId === task.id;
      const taskDisplay = isEditing
        ? `<input class="edit-input" data-id="${task.id}" value="${this.escapeHtml(task.text)}" aria-label="Edit task" />`
        : `<span class="task-text ${task.completed ? 'completed' : ''}">${this.escapeHtml(task.text)}</span>`;

      const actions = [];
      if (!task.completed) {
        actions.push(`<button class="complete-btn" data-id="${task.id}" aria-label="Mark as complete">Complete</button>`);
        actions.push(`<button class="edit-btn" data-id="${task.id}" aria-label="Edit task">Edit</button>`);
        actions.push(`<button class="delete-btn" data-id="${task.id}" aria-label="Delete task">Delete</button>`);
      } else {
        actions.push(`<button class="copy-btn" data-id="${task.id}" aria-label="Copy task">Copy</button>`);
        actions.push(`<button class="hide-btn" data-id="${task.id}" aria-label="Hide task">Hide</button>`);
      }

      li.innerHTML = `
        <div class="task-content">
          <input type="checkbox" ${task.completed ? 'checked disabled' : ''} aria-label="Mark task as complete" ${task.completed ? 'disabled' : ''} />
          ${taskDisplay}
          ${completionLabel}
        </div>
        <div class="task-actions">
          ${actions.join('')}
        </div>
      `;

      this.tasksList.appendChild(li);
    });
  }

  escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }
}

// Initialize the task manager when the DOM is loaded
document.addEventListener('DOMContentLoaded', () => {
  new TaskManager();
});
"}

