        align-items: flex-start;
        gap: 0.5rem;
    }

    .task-actions {
        align-self: flex-end;
    }
}

@media (max-width: 480px) {
    .task-form,
    .task-list {
        padding: 1rem;
    }

    input[type="text"] {
        padding: 0.75rem;
    }

