    padding: 1rem;
    border-bottom: 1px solid #e1e5e9;
    transition: background-color 0.3s ease;
}

li:last-child {
    border-bottom: none;
}

li:hover {
    background-color: #f8f9fa;
}

.task-text {
    flex: 1;
    margin-left: 1rem;
}

.task-text.completed {
    text-decoration: line-through;
    color: #6c757d;
}

.task-actions {
    display: flex;
    gap: 0.5rem;
}

.task-actions button {
    padding: 0.5rem 1rem;
    font-size: 0.9rem;
    border-radius: 3px;
}

.complete-btn {
    background: #28a745;
}

.complete-btn:hover {
    background: #218838;
}

.delete-btn {
    background: #dc3545;
}

.delete-btn:hover {
    background: #c82333;
}

/* Screen reader only class */
.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

/* Responsive design */
@media (max-width: 768px) {
    main {
        padding: 1rem;
    }

    h1 {
        font-size: 2rem;
    }

    form {
        flex-direction: column;
