// Task Manager JavaScript
class TaskManager {
  constructor() {
    this.tasks = JSON.parse(localStorage.getItem('tasks')) || [];
    this.taskForm = document.getElementById('add-task-form');
    this.taskInput = document.getElementById('task-input');
    this.tasksList = document.getElementById('tasks');
    this.filterButtons = document.querySelectorAll('.filter-btn');
    this.currentFilter = 'all';

    this.init();
  }

  init() {
    this.renderTasks();
    this.bindEvents();
  }

  bindEvents() {
    this.taskForm.addEventListener('submit', (e) => {
      e.preventDefault();
      this.addTask();
    });

    this.tasksList.addEventListener('click', (e) => {
      if (e.target.classList.contains('complete-btn')) {
        this.completeTask(e.target.dataset.id);
      } else if (e.target.classList.contains('copy-btn')) {
        this.copyTask(e.target.dataset.id);
      } else if (e.target.classList.contains('delete-btn')) {
        this.deleteTask(e.target.dataset.id);
      }
    });

    this.filterButtons.forEach((button) => {
      button.addEventListener('click', (e) => {
        this.setFilter(e.target.dataset.filter);
      });
    });
  }

  addTask() {
    const taskText = this.taskInput.value.trim();
    if (taskText === '') return;

    const task = {
      id: Date.now().toString(),
      text: taskText,
      completed: false,
      completedAt: null
    };

    this.tasks.push(task);
    this.saveTasks();
    this.renderTasks();
    this.taskInput.value = '';
    this.taskInput.focus();
  }

  completeTask(id) {
    const task = this.tasks.find((task) => task.id === id);
    if (task && !task.completed) {
      task.completed = true;
      task.completedAt = new Date().toISOString();
      this.saveTasks();
      this.renderTasks();
    }
  }

  copyTask(id) {
    const originalTask = this.tasks.find((task) => task.id === id);
    if (originalTask) {
      const newTask = {
        id: Date.now().toString(),
        text: originalTask.text + ' (copy)',
        completed: false,
        completedAt: null
      };
      this.tasks.push(newTask);
      this.saveTasks();
      this.renderTasks();
    }
  }

  deleteTask(id) {
    this.tasks = this.tasks.filter((task) => task.id !== id);
    this.saveTasks();
    this.renderTasks();
  }

  setFilter(filter) {
    this.currentFilter = filter;
    this.filterButtons.forEach((btn) => {
      btn.classList.toggle('active', btn.dataset.filter === filter);
    });
    this.renderTasks();
  }

  saveTasks() {
    localStorage.setItem('tasks', JSON.stringify(this.tasks));
  }

  formatCompletionTime(completedAt) {
    if (!completedAt) return '';

    const completedDate = new Date(completedAt);
    const now = new Date();
    const diffMs = now - completedDate;
    const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));
    const diffYears = Math.floor(diffDays / 365);

    // Same day - show relative time
    if (diffDays === 0) {
      const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
      if (diffHours === 0) {
        const diffMinutes = Math.floor(diffMs / (1000 * 60));
        return diffMinutes <= 1 ? 'Just now' : `${diffMinutes} minutes ago`;
      }
      return diffHours === 1 ? '1 hour ago' : `${diffHours} hours ago`;
    }

    // Same year - show month-date-hour-minute
    if (diffYears === 0) {
      const options = {
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      };
      return completedDate.toLocaleDateString('en-US', options);
    }

    // Different year - show year-month-date-hour-minute
    const options = {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    };
    return completedDate.toLocaleDateString('en-US', options);
  }

  getFilteredTasks() {
    switch (this.currentFilter) {
      case 'completed':
        return this.tasks.filter((task) => task.completed);
      case 'pending':
        return this.tasks.filter((task) => !task.completed);
      default:
        return this.tasks;
    }
  }

  renderTasks() {
    const filteredTasks = this.getFilteredTasks();
    this.tasksList.innerHTML = '';

    if (filteredTasks.length === 0) {
      const emptyMessage = document.createElement('li');
      const filterText = {
        all: 'No tasks yet. Add one above!',
        completed: 'No completed tasks yet.',
        pending: 'No pending tasks.'
      };
      emptyMessage.innerHTML = `<p style="text-align: center; color: #6c757d; font-style: italic;">${filterText[this.currentFilter]}</p>`;
      this.tasksList.appendChild(emptyMessage);
      return;
    }

    filteredTasks.forEach((task) => {
      const li = document.createElement('li');
      const completionTime = task.completed
        ? this.formatCompletionTime(task.completedAt)
        : '';
      const timeDisplay = completionTime
        ? `<small class="completion-time">${completionTime}</small>`
        : '';

      li.innerHTML = `
                <div class="task-content">
                    <input type="checkbox" id="task-${task.id}" ${task.completed ? 'checked disabled' : ''} aria-label="Mark task as complete">
                    <span class="task-text ${task.completed ? 'completed' : ''}" for="task-${task.id}">${this.escapeHtml(task.text)}</span>
                    ${timeDisplay}
                </div>
                <div class="task-actions">
                    ${!task.completed ? `<button class="complete-btn" data-id="${task.id}" aria-label="Mark as complete">Complete</button>` : `<button class="copy-btn" data-id="${task.id}" aria-label="Copy task">Copy</button>`}
                    <button class="delete-btn" data-id="${task.id}" aria-label="Delete task">Delete</button>
                </div>
            `;
      this.tasksList.appendChild(li);
    });
  }

  escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }
}

// Initialize the task manager when the DOM is loaded
document.addEventListener('DOMContentLoaded', () => {
  new TaskManager();
});

