    if (!task || task.completed) return;

    task.completed = true;
    task.completedAt = new Date().toISOString();
    this.saveTasks();
    this.renderTasks();
  }

  copyTask(id) {
    const original = this.tasks.find((task) => task.id === id);
    if (!original) return;

    const newTask = {
      id: Date.now().toString(),
